<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#72F088;">    image</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">: </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">nginx:1.25</span></span>
